const input = $input.first()?.json ?? {};
const required = ['tenant_id', 'calendar_id', 'google_event_id'];
const missing = required.filter((key) => input[key] === undefined || input[key] === null || String(input[key]).trim() === '');
if (missing.length) {
  return [{ json: { ...input, verification_status: 'failed', verification_reason: 'missing_context', missing_fields: missing } }];
}
return [{ json: { ...input, verification_status: 'pending', verification_reason: null } }];

const input = $('Validar Contexto Verificacao').item.json;
const event = $input.first()?.json ?? {};
const expectedStart = input.start_time ? new Date(input.start_time).getTime() : null;
const expectedEnd = input.end_time ? new Date(input.end_time).getTime() : null;
const actualStart = event.start?.dateTime ? new Date(event.start.dateTime).getTime() : null;
const actualEnd = event.end?.dateTime ? new Date(event.end.dateTime).getTime() : null;
const checks = {
  event_exists: Boolean(event.id),
  event_id_matches: String(event.id || '') === String(input.google_event_id),
  start_matches: expectedStart === null || actualStart === expectedStart,
  end_matches: expectedEnd === null || actualEnd === expectedEnd
};
const verified = Object.values(checks).every(Boolean);
return [{ json: { ...input, verification_status: verified ? 'verified' : 'failed', verification_reason: verified ? null : 'calendar_event_mismatch', verification_checks: checks, verified_event_id: event.id || null, verified_at: new Date().toISOString() } }];
